import { AnnotatedStringEdit, DiffAnnotation } from './annotatedStringEdit.js';
import { Move } from './move.js';

/**
 * Output of a diff computation.
 */
export class DiffResult {
	constructor(
		/**
		 * Parallel set of replacements transforming `original` into `modified`:
		 * `edits.apply(original) === modified` always holds. Moved text is part of
		 * these edits too (as a deletion and an insertion); `moves` only tells which
		 * deletions and insertions belong together. Whitespace changes are never dropped.
		 * Changes to leading/trailing whitespace of lines are annotated with
		 * `DiffAnnotation.trimWhitespace` so consumers can hide them.
		 */
		readonly edits: AnnotatedStringEdit<DiffAnnotation>,

		/**
		 * Detected moves of whole lines. Empty unless `DiffOptions.computeMoves` is set.
		 * Each move's `innerEdit` transforms the moved original text into the moved modified text.
		 * Only the TypeScript computer detects moves; the WASM computer returns none.
		 */
		readonly moves: readonly Move[],

		/**
		 * `true` if the algorithm aborted because of `maxComputationTimeMs`.
		 * The result is still valid but may be coarser than ideal.
		 */
		readonly hitTimeout: boolean,
	) { }
}

export interface DiffOptions {
	/**
	 * Algorithm hint. Pure-TS computer auto-selects based on input size if omitted.
	 * The WASM computer currently ignores this hint.
	 */
	algorithm?: 'myers' | 'dynamic-programming';

	/** Maximum computation time in milliseconds. 0 (default) means no timeout. */
	maxComputationTimeMs?: number;

	/** Detect moved blocks of lines (TypeScript computer only). Default: false. */
	computeMoves?: boolean;

	/** Extend diffs to subword boundaries. Default: false. */
	extendToSubwords?: boolean;
}

export interface IDiffComputer {
	computeDiff(original: string, modified: string, options?: DiffOptions): DiffResult;
}
